/* ---- 签名与请求 ---- */
function 时间戳() {
    var d = new Date();
    return d.getFullYear() + '0' + (d.getMonth() + 1) + '0' + d.getDate() + '0' + d.getDay() + d.getMinutes() + d.getSeconds();
}
function 请求头(sign, type) {
    var h = {
        'pname': XGPN, 'sign': sign, 'signType': sh(type),
        'Accept': 'application/json', 'Content-Type': 'application/json; charset=UTF-8'
    };
    if (sh(type) === '2') { h['uid'] = XGUID; }
    return h;
}
/* 普通接口：HMAC-SHA256 签名 */
function 接口(path, obj) {
    var body = JSON.stringify(obj), t = 时间戳();
    var sign = XG.b64(XG.hmac(XGKEY, XGQS + '&timestamp=' + t + body + XGSALT));
    var r = postText(XGAPI + path + '?' + XGQS + '&timestamp=' + t, body, 请求头(sign, 1), false);
    var j = jparse(r);
    if (!j) { return { err: '接口没响应（' + path + '）' }; }
    if (sh(j.retCode) !== '0') { return { err: '接口返回 ' + sh(j.retCode) + ' ' + sh(j.retMsg) }; }
    return { data: j.data || {} };
}

/* 列表：西瓜只有检索接口，分类按钮=按题材检索 */
function 列表(kw, pg) {
    var r = 接口('1141', { size: 15, searchType: '', index: num(pg || 1), keyword: sh(kw) });
    if (r.err) { return { ok: false, err: r.err }; }
    var arr = (r.data.searchList) || [], out = [], i, b;
    for (i = 0; i < arr.length; i++) {
        b = arr[i];
        if (!b || !b.bookId) { continue; }
        out.push({
            i: sh(b.bookId), t: sh(b.bookName), a: sh(b.author), g: '',
            w: '', n: '', s: '', d: strip(b.introduction), p: sh(b.coverWap)
        });
    }
    return { ok: out.length > 0, list: out, err: out.length ? '' : '这个题材没搜到书' };
}

/* 目录：1110 拿简介/封面，111 一次给全书章节 */
function 目录(bid) {
    var d = 接口('1110', { bookId: sh(bid) });
    if (d.err) { return { ok: false, err: d.err }; }
    var b = d.data.book || {};
    var m = {
        n: sh(b.bookName), a: sh(b.author), d: strip(b.introduction), g: sh(b.cp || ''),
        w: sh(b.totalWordSize).replace(/[^0-9.万亿]/g, ''), p: sh(b.coverWap),
        l: sh((d.data.lastChapter || {}).chapterName)
    };
    var t = 接口('111', { chapterId: '', needBlockList: '1', chapterOffset: '666666', bookId: sh(bid), chapterEndId: '' });
    if (t.err) { return { ok: false, err: t.err }; }
    var ids = t.data.chapterIdList || [], names = t.data.chapterNameList || [];
    var ch = [], i;
    for (i = 0; i < ids.length; i++) {
        if (!ids[i]) { continue; }
        ch.push([num(ids[i]), strip(names[i]) || ('第' + (i + 1) + '章')]);
    }
    if (!ch.length) { return { ok: false, err: '目录是空的' }; }
    return { ok: true, m: m, ch: ch };
}

/* 正文：1150 只走 HMAC 就能拿 cdnUrls（比 1152 的 RSA 快得多）；失败再退 1152 */
function 正文(bid, no) {
    var body = JSON.stringify({ autoPay: '1', chapterId: sh(no), keepShowAd: 1, confirmPay: '1', bookId: sh(bid) });
    var info = 取章节(body, '1150');
    if (!info || !(info.cdnUrls || []).length) {
        info = 取章节(body, '1152');   // 备用：要 RSA 签名
    }
    if (!info || !(info.cdnUrls || []).length) { return { ok: false, err: '取正文失败，换个源或稍后重试' }; }

    var urls = info.cdnUrls, i, txt = '';
    for (i = 0; i < urls.length && txt.length < 50; i++) {
        txt = sh(getText(urls[i], 'https://xgmf.zuanqianyi.com/', 1, { 'User-Agent': CFG.ua }));
    }
    if (txt.length < 20) { return { ok: false, err: '正文 CDN 没取到' }; }
    txt = txt.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '');
    var lines = txt.split(/\r?\n/), p = [], x;
    for (i = 0; i < lines.length; i++) {
        x = strip(lines[i]);
        if (x) { p.push(x); }
    }
    if (p.length > 1 && /^第[0-9一二三四五六七八九十百千零]+章/.test(p[0])) { p.shift(); }
    if (!p.length) { return { ok: false, err: '正文是空的' }; }
    return { ok: true, t: sh(info.chapterName) || ('第' + no + '章'), p: p };
}

/* 取章节信息：path=1150 用 HMAC；path=1152/1153 用 RSA */
function 取章节(body, path) {
    var j = null, t, sign;
    if (path === '1150') {
        t = 时间戳();
        sign = XG.b64(XG.hmac(XGKEY, XGQS + '&timestamp=' + t + body + XGSALT));
        j = jparse(postText(XGAPI + path + '?' + XGQS + '&timestamp=' + t, body, 请求头(sign, 1), false));
    } else {
        t = 时间戳();
        sign = XG.rsaSign(XGQS + '&timestamp=' + t + body + XGSALT, XGRSA);
        j = jparse(postText(XGAPI + path + '?' + XGQS + '&timestamp=' + t, body, 请求头(sign, 2), false));
        if (!j || sh(j.retCode) !== '0') {
            t = 时间戳();
            sign = XG.rsaSign(XGQS + '&timestamp=' + t + body + XGSALT, XGRSA);
            j = jparse(postText(XGAPI + '1153?' + XGQS + '&timestamp=' + t, body, 请求头(sign, 2), false));
        }
    }
    if (!j || sh(j.retCode) !== '0') { return null; }
    return (j.data && j.data.chapterInfo && j.data.chapterInfo[0]) || null;
}

